const n="// Slot 分析 Toolbar 测试脚本\r\n// 上下文变量：$api, $route, $data, $el, $query, $queryAll, $rebindRules, $refreshData, $dataSet, $call 都已注入\r\n\r\n// 页面初始化\r\nconsole.log('Slot Toolbar Test initialized')\r\n\r\n// 注册页面函数\r\nregisterFunction('__init__', function() {\r\n  console.log('Slot Toolbar Test initialized via registerFunction')\r\n})\r\n\r\nregisterFunction('handleAddUser', function() {\r\n  console.log('添加用户按钮被点击')\r\n  const dataSet = $dataSet()\r\n  const users = $data().dataset.tables.Users.rows\r\n  const newUser = {\r\n    id: users.length + 1,\r\n    name: `用户${users.length + 1}`,\r\n    email: `user${users.length + 1}@example.com`,\r\n    status: '活跃'\r\n  }\r\n  users.push(newUser)\r\n  dataSet.notifySubscribers('Users')\r\n})\r\n\r\nregisterFunction('handleExportData', function() {\r\n  console.log('导出数据按钮被点击')\r\n  const users = $data().dataset.tables.Users.rows\r\n  console.log('导出用户数据:', users)\r\n})\r\n\r\nregisterFunction('handleSmartButton', function() {\r\n  console.log('智能按钮被点击')\r\n  ElMessage.success('智能按钮点击成功！')\r\n})";export{n as default};
